import logging
import os
import time

from ta_ue_plugin_android.uepc.ftp_control import FtpControl
from ta_ue_plugin_android.uepc.ssh_manager import SshManager
from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeNotRootedException, FileWasNotFoundError
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra
from ta_ue_plugin_android.uepc.utils import Utils

raw_logger = logging.getLogger("ute_ue.uepc")
logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UTILS'})


class UeControlUtils(object):
    """Module responsible for handle tasks related to an Android UE."""
    CMD_FOR_ROOT_CHECK = 'su'

    def __init__(self, ue_control):
        """
        Basic initialization.
        :param ue_control:
        """
        self.ue_control = ue_control
        self.ssh_manager = SshManager()

    def kill_process_with_phrase(self, process_phrase):
        """
        Method used to kill process on Android UE
        :param process_phrase: all processes with this phrase in its name will terminate
        """
        cmd = 'ps | grep -i {}'.format(process_phrase)
        out = self._run_cmd_on_android_ue_and_return_output(cmd)
        for element in out:
            ps_lst = element.split()
            if len(ps_lst) >= 2:
                pid = ps_lst[1]
                self.kill_by_pid(pid)

    def kill_proc_on_ue_by_busybox(self, proc_name):
        """
        Method uses busybox app to kill process on Android UE
        :param proc_name: process name to terminate
        """
        self.check_busybox_is_installed()
        cmd = 'busybox ps | grep {}'.format(proc_name)
        out = self._run_cmd_on_android_ue_and_return_output(cmd)
        for element in out:
            ps_lst = element.split()
            pid = ps_lst[0]
            self.kill_by_pid(pid)

    def kill_by_pid(self, pid):
        """
        Method used to kill specific PID on Android UE
        :param pid: Android PID
        """
        cmd = 'kill {}'.format(pid)
        logger.info('kill cmd: {}'.format(cmd))
        reader = self.ue_control.run_cmd_and_get_non_blocking_output(cmd)
        return self.non_blocking_to_string_by_blocking(reader)

    def get_su_prefix(self):
        """Checks if Android UE is rooted, raises exception when UE is not rooted"""
        is_rooted, su_prefix = self.ue_control.is_rooted()
        if not is_rooted:
            raise UeNotRootedException()
        return su_prefix

    def _run_cmd_via_adb_shell_and_check_output(self, args_list, txt_to_fail=None):
        result, err = self.ue_control.run_cmd_via_adb('shell', args_list)
        logger.debug('Checking if txt_to_fail "{}" is available in result.'.format(txt_to_fail))
        if txt_to_fail is not None and txt_to_fail in result:
            raise Exception(result, err)
        logger.debug('command run via ADB: adb shell {}, output: {}'.format(args_list, result))
        return result, err

    def _run_cmd_on_android_ue_and_return_output(self, cmd, timeout=300):
        out = self.ue_control.run_cmd_and_get_non_blocking_output(cmd)
        logger.debug('command run on UE: {}, output: {}'.format(cmd, out))
        return UeControlUtils.non_blocking_to_string_by_blocking(out, timeout)

    def _run_background_process_on_android_ue_and_return_pid(self, cmd):
        reader = self.ue_control.run_cmd_and_get_non_blocking_output('{cmd} > /dev/null & echo $!'.format(cmd=cmd))
        out = self.non_blocking_to_string_by_blocking(reader)
        logger.debug('command run on UE: {}, pid: {}'.format(cmd, out))
        if not out:
            raise Exception('Failed to start process: {}'.format(out))
        return out[0]

    @staticmethod
    def non_blocking_to_string_by_blocking(out, timeout=300, expect_output=False):
        """
        Returns output from stream as a list
        :param out:
        :param timeout:
        :return:
        """
        return Utils().get_non_blocking_reader_result(out, timeout=timeout, expect_output=expect_output)

    def adb_push_file(self, file_local_path, file_ue_path):
        """
        Push file to Android UE via ADB
        :param file_local_path: path to local file on UE PC
        :param file_ue_path: target path on Android UE
        """
        self.ue_control.adb_push_file(file_local_path, file_ue_path)

    def adb_pull_file(self, file_local_path, file_ue_path):
        """
        Pull file from Android UE to UE PC via ADB
        :param file_local_path: target path to local file on UE PC
        :param file_ue_path: file path on Android UE
        """
        self.ue_control.adb_pull_file(file_local_path, file_ue_path)

    def check_busybox_is_installed(self):
        """Method checking if busybox application is installed on UE"""
        logger.debug('Checking if busybox is installed')
        result, _ = self._run_cmd_via_adb_shell_and_check_output(['busybox'], txt_to_fail='not found')
        logger.debug('Busybox is installed!')
        return result

    def http_request(self, url):
        """
        Trigger HTTP GET message from UE to given URL
        :param url:   url to a file on a remote web server
        :return:
        """
        self.check_busybox_is_installed()
        http_cmd = 'busybox wget -s {}'.format(url)
        logger.debug(http_cmd)
        out, err = self._run_cmd_via_adb_shell_and_check_output([http_cmd])
        logger.debug(out)
        if not out:
            out = err
        _verify_http_out(out.splitlines(), url)

    def transfer_file_from_ftp(self, local_path, remote_path, ftp_ip, ftp_user=None, ftp_pass=None, ftp_port=21):
        """
        Transfer a file from FTP server to UE
        :param ftp_ip: FTP IP
        :param remote_file_path: path to file on FTP server
        :param ftp_port: FTP port, by default = 21
        :param ftp_user: FTP user, None by default
        :param ftp_pass: FTP password, None by default
        :return:
        """
        self.check_busybox_is_installed()
        self._mkdir_on_android(local_path)
        filename = os.path.basename(remote_path)
        local_file_path = '{}/{}'.format(local_path, filename)
        logger.debug(local_file_path)

        logger.info('File transfer from FTP to UE start.')
        if ftp_user is None and ftp_pass is None:
            ftpget_cmd = 'busybox ftpget -P {} {} {} {}'.format(ftp_port, ftp_ip, local_file_path, remote_path)
            logger.debug(ftpget_cmd)
            pid = self._run_background_process_on_android_ue_and_return_pid(ftpget_cmd)
        else:
            ftpget_cmd = 'busybox ftpget -P {} -u {} -p {} {} {} {}'.format(
                ftp_port, ftp_user, ftp_pass, ftp_ip, local_file_path, remote_path)
            logger.debug(ftpget_cmd)
            pid = self._run_background_process_on_android_ue_and_return_pid(ftpget_cmd)

        _verify_ftp_out(pid)

        logger.debug('Checking if file exists on ftp server')
        self.check_if_android_file_exists(local_file_path)
        logger.debug('File found!')

        return ftpget_cmd, pid

    def transfer_file_to_ftp(self, local_path, remote_path, ftp_ip, ftp_user=None, ftp_pass=None, ftp_port=21):
        """
        Transfer a file from UE to FTP server
        :param ftp_ip: FTP IP
        :param local_file_path: path to a file on UE
        :param remote_dir_path: path to dir on FTP server
        :param ftp_user: FTP server username
        :param ftp_pass: FTP server password
        :param ftp_port: FTP port, 21 by default
        """
        logger.debug('Checking if busybox is installed')
        self.check_busybox_is_installed()

        self.check_if_android_file_exists(local_path)
        filename = os.path.basename(local_path)
        logger.debug(filename)

        remote_file_path = '{}/{}'.format(remote_path, filename)

        ftpput_cmd = 'busybox ftpput -P {} -u {} -p {} {} {} {}'.format(ftp_port, ftp_user, ftp_pass, ftp_ip,
                                                                        remote_file_path, local_path)
        logger.debug(ftpput_cmd)

        logger.info('File transfer from UE to FTP start.')
        pid = self._run_background_process_on_android_ue_and_return_pid(ftpput_cmd)
        logger.info('File transfer from UE to FTP started')

        _verify_ftp_out(pid)
        _await_file_on_ftp(remote_file_path, ftp_ip, ftp_user, ftp_pass)

        return ftpput_cmd, pid

    def remove_file_on_android(self, filepath):
        """
        Remove a file on Android UE
        :param filepath: path to a file on Android UE
        """
        logger.info('Removing file {} on android.'.format(filepath))
        rm_cmd = 'rm {}'.format(filepath)
        self.check_if_android_file_exists(filepath)
        self._run_cmd_on_android_ue_and_return_output(rm_cmd)

    def remove_file_on_ftp(self, ftp_ip, ftp_user, ftp_pass, file_path):
        """Removes file on ftp"""
        ftp = FtpControl(ftp_ip, ftp_user, ftp_pass)
        ftp.login_to_ftp()
        ftp.remove_file(file_path)
        if ftp.check_if_file_exists(file_path) == 1:
            raise Exception('The file was not deleted from FTP server!')

    def check_if_android_file_exists(self, filepath):
        """
        Check if a file on Android UE exists
        :param filepath: path to a file on Android UE
        """
        logger.debug('Checking if file {} on Android exists.'.format(filepath))
        out, _ = self._run_cmd_via_adb_shell_and_check_output(['ls', filepath], txt_to_fail='not found')
        if not out:
            raise FileWasNotFoundError('File {} not found on Android!'.format(filepath))
        logger.debug('File found.')

    def _mkdir_on_android(self, folder_path):
        cmd = 'mkdir {}'.format(folder_path)
        self._run_background_process_on_android_ue_and_return_pid(cmd)


def _verify_http_out(out, url):
    out = ' '.join(out)
    errors = {'HTTP/1.1 4': 'HTTP 4xx Error: {}'.format(out),
              'timeout': 'Can not connect to HTTP server, check the url {}'.format(url),
              'timed out': 'Can not connect to HTTP server, check the url {}'.format(url),
              'error': 'Some error occured during http request. Wget output: {}!'.format(out),
              'Network is unreachable': 'Network unreachable error, check if UE is attached or has Mobile Data ON. '
                                        'Wget output: {}!'.format(out),
              'bad address': 'Wrong url {}. Wget output: {}!'.format(url, out),
              'Connection refused': 'Connection refused by the server. Wget output: {}!'.format(out)}

    for error, msg in errors.items():
        if error in out:
            raise Exception(msg)


def _verify_ftp_out(out):
    out = ' '.join(out)
    errors = {'error': 'Some error ocured during http request. Wget output: {}!'.format(out),
              'Network is unreachable': 'Network unreachable error, check if '
                                        'UE is attached or has Mobile Data ON. Wget output: {}!'.format(out),
              'No such file or directory': 'No such file or directory: {}'.format(out)}

    for error, msg in errors.items():
        if error in out:
            raise Exception(msg)


def _await_file_on_ftp(remote_file_path, ftp_ip, ftp_user, ftp_pass, timeout=30):
    logger.debug('Awaiting file {} appears on FTP server (timeout=30s)'.format(remote_file_path))
    ftp = FtpControl(ftp_ip, ftp_user, ftp_pass)
    ftp.login_to_ftp()
    success = False
    end_time = time.time() + timeout
    while time.time() < end_time:
        if ftp.check_if_file_exists(remote_file_path) == 1:
            success = True
            break
    if not success:
        raise Exception('Could not find a file on FTP server!')
